PREFIX int: <https://github.com/prcgui/bim-ontology-CIV2155/vocab/integracao#>
PREFIX civ: <https://github.com/prcgui/bim-ontology-CIV2155/vocab/analise#>
SELECT ?ambiente ?nome ?estado ?esquadrias ?modelo ?relacoes
WHERE { ?resultado a civ:ResultadoPorAmbiente ; civ:ambiente ?ambiente ; civ:nome ?nome ; civ:estado ?estado .
 OPTIONAL { ?resultado civ:quantidadeEsquadrias ?esquadrias }
 OPTIONAL { SELECT ?ambiente ?modelo (COUNT(?r) AS ?relacoes) WHERE {
 ?r a int:RelacaoEspacial ; int:ambiente ?ambiente ; int:modelo ?m . ?m int:chave ?modelo
 } GROUP BY ?ambiente ?modelo }
} ORDER BY ?nome ?modelo

PREFIX int: <https://github.com/prcgui/bim-ontology-CIV2155/vocab/integracao#>
PREFIX civ: <https://github.com/prcgui/bim-ontology-CIV2155/vocab/analise#>
PREFIX props: <http://lbd.arch.rwth-aachen.de/props#>
SELECT ?ambiente ?elemento ?predicado ?estado ?areaM2 ?volumeM3 ?modelo ?grafo ?sha256
WHERE { ?resultado civ:nome "COZINHA" ; civ:ambiente ?ambiente .
 ?elemento props:globalIdIfcRoot_attribute_simple "0EVSuIeKOHxuDHo7zKqQBn" .
 GRAPH <https://github.com/prcgui/bim-ontology-CIV2155/grafo/relacoes> {
 ?r a int:RelacaoEspacial ; int:ambiente ?ambiente ; int:elementoEstrutural ?elemento ;
 int:predicado ?predicado ; int:estado ?estado ; int:areaContatoM2 ?areaM2 ; int:volumeIntersecaoM3 ?volumeM3 ; int:modelo ?m }
 ?m int:chave ?modelo ; int:grafo ?grafo ; int:sha256IFC ?sha256 . }

PREFIX civ: <https://github.com/prcgui/bim-ontology-CIV2155/vocab/analise#>
SELECT ?ambiente ?nome ?motivo ?quantidade
WHERE { ?r a civ:ResultadoPorAmbiente ; civ:ambiente ?ambiente ; civ:nome ?nome ;
 civ:estado "inconclusivo_preparacao_espaco" .
 OPTIONAL { ?r civ:motivo ?motivo } OPTIONAL { ?r civ:quantidadeEsquadrias ?quantidade } }
ORDER BY ?nome

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?grafo ?classe ?superclasse
WHERE { GRAPH ?grafo { ?classe rdfs:subClassOf ?superclasse }
 FILTER(?grafo IN (<https://github.com/prcgui/bim-ontology-CIV2155/grafo/perfil>, <https://github.com/prcgui/bim-ontology-CIV2155/grafo/bot-referencia>)) }
ORDER BY ?grafo ?classe
